__global__ void fft_columns_kernel(float2* x, int rows, int cols) {
    int col = threadIdx.x + blockIdx.x * blockDim.x;
    int batch = threadIdx.y + blockIdx.y * blockDim.y;

    if (col >= cols || batch >= batch) return;

    // Calculate the start index for this column in the matrix
    int start_idx = batch * rows * cols + col;

    // Initialize the output array for this column
    float2* column = x + start_idx;

    // Compute the FFT for this column
    cuFFT::fft1d(column, rows, CUDA_C_32F, CUDA_R2C, stream);
}
