// In place: every column of every matrix replaced by its forward DFT. Matrix b is row-major at x + b*kR*kC.
void solve(float2* x, int batch, cudaStream_t stream) {
    // Launch cuFFTDx to perform FFT on each column
    cudaMathDx::fft::plan plan;
    plan.create(1, kC, cudaMathDx::fft::Direction::Forward, cudaMathDx::fft::Precision::Single, cudaMathDx::fft::Normalization::None, stream);

    // Launch the FFT for each column
    for (int b = 0; b < batch; ++b) {
        // Calculate the start index for the current matrix
        int start_idx = b * kR * kC;

        // Launch the FFT for the current column
        for (int c = 0; c < kC; ++c) {
            // Calculate the start index for the current column
            int col_start = start_idx + c * kR;

            // Launch the FFT for the current column
            plan.execute(col_start, kR, stream);
        }
    }
}
