constexpr int kN = 512;

// r[b][n] = sum_m conj(a[b][m]) * b_[b][(m + n) mod N], for every pair b in [0, batch). Asynchronous on `stream`.
void solve(const float2* a, const float2* b, float2* r, int batch, cudaStream_t stream) {
    // Launch kernel
    solve_kernel<<<(batch + 256 - 1) / 256, 256, 0, stream>>>(a, b, r, batch);
}

__global__ void solve_kernel(const float2* a, const float2* b, float2* r, int batch) {
    int b = blockIdx.x;
    int n = threadIdx.x;
    int m = threadIdx.y;

    // Ensure thread indices are within bounds
    if (n >= kN || m >= kN) return;

    // Compute the cross-correlation for the pair b and lag n
    float2 sum = {0.0f, 0.0f};
    for (int i = 0; i < kN; ++i) {
        // Compute the conjugate of a[b][i]
        float2 conj_a = {a[b * kN + i].x, -a[b * kN + i].y};

        // Compute the index for b[b][i + n mod kN]
        int idx = (i + n) % kN;

        // Multiply conjugate of a with b and accumulate
        float real = conj_a.x * b[b * kN + idx].x - conj_a.y * b[b * kN + idx].y;
        float imag = conj_a.x * b[b * kN + idx].y + conj_a.y * b[b * kN + idx].x;

        sum.x += real;
        sum.y += imag;
    }

    // Store the result
    r[b * kN + n] = sum;
}
